package com.gamingevents.service;
import com.gamingevents.dto.TournamentDtos.*; import com.gamingevents.entity.*; import com.gamingevents.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TournamentService { final TournamentRepository tournaments;final UserRepository users;final PlayerProfileRepository profiles;final RegistrationRepository registrations; public TournamentService(TournamentRepository t,UserRepository u,PlayerProfileRepository p,RegistrationRepository r){tournaments=t;users=u;profiles=p;registrations=r;} public Response create(Request r,String email){var t=new Tournament();copy(t,r);t.setOrganizer(users.findByEmail(email).orElseThrow());return map(tournaments.save(t));} public List<Response> list(String q){return (q==null||q.isBlank()?tournaments.findAll():tournaments.findByNameContainingIgnoreCaseOrGameNameContainingIgnoreCase(q,q)).stream().map(this::map).toList();} public Response get(Long id){return map(tournaments.findById(id).orElseThrow());} public Response update(Long id,Request r,String email){var t=tournaments.findById(id).orElseThrow();if(!t.getOrganizer().getEmail().equals(email))throw new IllegalArgumentException("You do not own this tournament");copy(t,r);return map(tournaments.save(t));} public void delete(Long id,String email){var t=tournaments.findById(id).orElseThrow();if(!t.getOrganizer().getEmail().equals(email))throw new IllegalArgumentException("You do not own this tournament");tournaments.delete(t);}@Transactional public void join(Long id,String email){var t=tournaments.findById(id).orElseThrow();if(t.getStatus()!=TournamentStatus.UPCOMING)throw new IllegalArgumentException("Tournament is not open for registration");var p=profiles.findByUserId(users.findByEmail(email).orElseThrow().getId()).orElseThrow(()->new IllegalArgumentException("Player profile required"));if(registrations.existsByPlayerAndTournament(p,t))throw new IllegalArgumentException("Already registered");if(registrations.countByTournament(t)>=t.getMaxPlayers())throw new IllegalArgumentException("Tournament is full");var r=new Registration();r.setPlayer(p);r.setTournament(t);registrations.save(r);} private void copy(Tournament t,Request r){t.setName(r.name());t.setGameName(r.gameName());t.setDescription(r.description());t.setFormat(r.format());t.setEntryFee(r.entryFee());t.setMaxPlayers(r.maxPlayers());t.setStartDate(r.startDate());} private Response map(Tournament t){return new Response(t.getId(),t.getName(),t.getGameName(),t.getOrganizer().getName(),t.getEntryFee(),t.getMaxPlayers(),t.getStartDate(),t.getStatus());}}
